function renderConfig(event: H3Event): H3Config {
  const config = event.app?.config;
  return config ? { debug: config.debug, problemDetails: config.problemDetails } : {};
}

function errorResponse(error: HTTPError, config: H3Config, errHeaders?: Headers): Response {
  const base = config.problemDetails ? problemHeaders : jsonHeaders;
  let headers: Headers = error.headers ? mergeHeaders(base, error.headers) : new Headers(base);
  if (errHeaders) {
    headers = mergeHeaders(headers, errHeaders);
  }
  const debug = config.debug;
  const body = config.problemDetails
    ? toProblemJSON(error, debug)
    : {
        ...error.toJSON(),
        stack: debug && error.stack ? error.stack.split("\n").map((l) => l.trim()) : undefined,
      };
  return new FastResponse(JSON.stringify(body, undefined, debug ? 2 : undefined), {
    status: error.status,
    statusText: error.statusText,
    headers,
  });
}

/**
 * RFC 9457 problem details body. RFC members take precedence over `body` keys, and an unhandled
 * error exposes neither its `type` nor its `instance`, which come from application code.
