// Measures bundle size of HEAD's src/ (from git objects) against the working tree's src/.
import { execSync } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import zlib from "node:zlib";

const REPO = "C:/dev/runs/r20c96ec1cf";
const OUT = "C:/Users/caiog/AppData/Local/Temp/claude/C--dev-runs-r20c96ec1cf/8ad62be0-7269-47da-afef-a8d049c5c7c9/scratchpad/head";
const { build } = await import("file:///C:/dev/runs/r20c96ec1cf/node_modules/esbuild/lib/main.js");

const files = execSync("git ls-tree -r --name-only HEAD src", { cwd: REPO })
  .toString()
  .trim()
  .split("\n");
for (const f of files) {
  const content = execSync(`git show HEAD:${f}`, { cwd: REPO, maxBuffer: 1 << 26 });
  mkdirSync(dirname(join(OUT, f)), { recursive: true });
  writeFileSync(join(OUT, f), content);
}

async function size(srcDir) {
  const code = `import { H3Core } from "${srcDir}/index.ts";\nconst app = new H3Core();\n`;
  const res = await build({
    bundle: true,
    metafile: true,
    write: false,
    minify: true,
    format: "esm",
    platform: "node",
    outfile: "index.mjs",
    treeShaking: true,
    conditions: ["browser"],
    logOverride: { "ignored-bare-import": "silent" },
    nodePaths: [`${REPO}/node_modules`],
    stdin: { contents: code, resolveDir: srcDir, sourcefile: "index.mjs", loader: "js" },
  });
  return {
    bytes: res.metafile.outputs["index.mjs"].bytes,
    gzip: zlib.gzipSync(res.outputFiles[0].text).byteLength,
  };
}

console.log("HEAD     ", await size(`${OUT}/src`));
console.log("working  ", await size(`${REPO}/src`));

